      "correct": "בהלם עצבי (נוירוגני), הפוגע במסלולי המערכת הסימפתטית (כתוצאה מפגיעת עמוד שדרה), מופיע דופק נורמלי או איטי (ברדיקרדי) יחד עם לחץ דם נמוך — בשונה משאר סוגי ההלם, המאופיינים בד\"כ בטכיקרדיה מפצה.\n\nטבלת סוגי הלם — קצב הדופק האופייני:\n— הלם תת-נפחי (היפוולמי): דופק מהיר (טכיקרדיה מפצה).\n— הלם לבבי (קרדיוגני): דופק מהיר (או הפרעת קצב).\n— הלם זיהומי (ספטי): דופק מהיר.\n— הלם אנפילקטי: דופק מהיר.\n— הלם עצבי (נוירוגני): דופק תקין/איטי — כיוון שהמערכת הסימפתטית (האחראית להאצת הדופק) פגועה ואינה יכולה לפצות.",
