    "question": "נקראת לבן 50 בעקבות תלונה על כאבים בחזה. בהגעתך למקום הנך מבחין באדון יושב על כיסא, בבדיקה: בהכרה מלאה, כאוב מאוד, מתאר כאב לוחץ במרכז בית החזה עם הקרנה לגב, נושם 20 נשימות בדקה, חיוור מאוד ומזיע.מציין שהכאב החל במנוחה ושולל אירוע דומה בעבר. במה תחשוד וכיצד תטפל?",
