      "correct": "מטופל ג' (חולשה בפלג גוף שמאלי, הפרעה בדיבור, סטורציה תקינה 96%) — סימני שבץ מוחי, אך ללא היפוקסיה (סטורציה תקינה). מטופל זה אינו זקוק בהכרח לחמצן טרם/במהלך הפינוי, שכן חמצן שגרתי אינו מומלץ כשאין היפוקסיה — טיפול ה-Stroke מתמקד בפינוי מהיר, לא חמצן שגרתי.",
