    "question": "הוזעקת לטפל בגברת בת 26 בהריון. בתשאול: בריאה בדרך כלל, בשבוע 30 להריונה, מתלוננת על טשטוש ראיה וכאבי ראש חזקים. בבדיקה: בהכרה מלאה, דופק 90 בדקה, סדיר, לחץ דם: 170/100, סוכר: 65mg/dL. במהלך ההעברה למיטת האמבולנס המטופלת החלה לפרכס. במה תחשוד וכיצד תנהג?",
