    "question": "הוזעקת לתאונת דרכים קשה בין משאית לאופנוע. בהגעתך לזירת האירוע הנך מוצא את רוכב האופנוע שוכב על הכביש כאשר הראש מנותק משאר הגוף. כיצד עליך לפעול?",
