    "question": "הוזעקת לטפל בגבר כבן 40 שחש ברע והתמוטט במהלך טיול במדבר יהודה בחודש אוגוסט. לדברי חבריו, לא שתה מזה מספר שעות. בבדיקה: מגיב לכאב, נושם 26 נשימות בדקה, דופק רדיאלי 130 פעימות בדקה, עור סמוק וחם מאוד למגע. במה תחשוד?",
