      "correct": "יש להסיר את הקסדה בשטח (לא להשאירה ולא להמתין) בטכניקה מבוקרת של שני מטפלים: אחד מקבע את הראש והצוואר בקו ניטרלי מלמטה תוך כדי הסרת הקסדה, והשני מסיר אותה בעדינות — כדי לאפשר גישה לנתיב אוויר, בדיקה ראשונית וקיבוע נכון ללוח שדרה תוך מזעור תנועת עמוד השדרה הצווארי.",
