    "question": "הוזעקת לאירוע של קטטה. בהגעתך למקום הנך מוצא פצוע בן 22 יושב על המדרכה כאשר סכין נעוצה לו בגב. בבדיקה: בהכרה, כאוב, חיוור ומזיע, דופק 120 פעימות בדקה. מהו הטיפול המומלץ?",
