      "wrong": "א' (לחץ דם) עשוי לעלות רק בשלב מאוחר ומתקדם של פגיעת ראש (חלק ממשולש קושינג), ולכן פחות רגיש כמדד מוקדם. ב' (דופק) הוא דווקא המדד המרכזי להערכת הלם, לא פגיעת ראש. ד' (מצב נשימתי) יכול להצביע על פגיעה בגזע המוח בשלב מתקדם, אך אינו הרגיש והמוקדם ביותר בהשוואה לרמת ההכרה."
