      "correct": "קיבוע ראש ידני (In-line Stabilization) מבוצע כבר בשלב ה-A (Airway) הראשוני של הסבב הראשוני בסכמת ה-PHTLS — יחד עם פתיחת נתיב האוויר (כדוגמת Jaw Thrust) — כדי למנוע תזוזה נוספת של עמוד השדרה הצווארי כבר מרגע ההתקרבות הראשונית למטופל טראומה.",
